import sys, json, math

def mean(a):
    return sum(a) / len(a)

def var(a):
    m = mean(a)
    return sum((x - m) ** 2 for x in a) / (len(a) - 1)

def compare(xs, ys):
    n, m = len(xs), len(ys)
    pv = ((n - 1) * var(xs) + (m - 1) * var(ys)) / (n + m - 2)
    cohen = abs(mean(xs) - mean(ys)) / (math.sqrt(pv) + 1e-32)
    s = 0
    for x in xs:
        for y in ys:
            s += (x > y) - (x < y)
    cliffs = abs(s) / (n * m)
    sx, sy = sorted(xs), sorted(ys)
    import bisect
    d = 0.0
    for v in set(xs) | set(ys):
        d = max(d, abs(bisect.bisect_right(sx, v) / n - bisect.bisect_right(sy, v) / m))
    ks = d / math.sqrt(1 / n + 1 / m)
    same = cohen <= 0.35 and cliffs <= 0.197 and ks <= 1.36
    return {"cohen": cohen, "cliffs": cliffs, "ks": ks, "same": bool(same)}

def main():
    a = sys.argv[1:]
    if not a or a[0] != "certify":
        sys.exit(1)
    path = a[a.index("--test") + 1]
    with open(path) as f:
        cases = json.load(f)
    out = {"comparisons": [compare([float(x) for x in c["xs"]], [float(y) for y in c["ys"]]) for c in cases]}
    sys.stdout.write(json.dumps(out))

main()
